import{_ as s,o as t,c as a,a2 as n}from"./chunks/framework.DRsMviRd.js";const u=JSON.parse('{"title":"Inspect the supervision tree","description":"","frontmatter":{},"headers":[],"relativePath":"agent-data-plane/supervision-tree.md","filePath":"agent-data-plane/supervision-tree.md","lastUpdated":1790106376000}'),r={name:"agent-data-plane/supervision-tree.md"};function o(i,e,d,p,c,h){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="inspect-the-supervision-tree" tabindex="-1">Inspect the supervision tree <a class="header-anchor" href="#inspect-the-supervision-tree" aria-label="Permalink to &quot;Inspect the supervision tree&quot;">​</a></h1><p>Use <code>agent-data-plane debug runtime show-processes</code> to see which processes Agent Data Plane (ADP) is running, how they are nested, which have restarted, and how much memory and CPU each accounts for.</p><h2 id="understand-what-the-tree-reports" tabindex="-1">Understand what the tree reports <a class="header-anchor" href="#understand-what-the-tree-reports" aria-label="Permalink to &quot;Understand what the tree reports&quot;">​</a></h2><p>ADP&#39;s runtime is a supervision tree: every unit of work is a <em>process</em> supervised by a <em>supervisor</em>, and supervisors nest to form the tree. That structure is the most complete description of what ADP is doing, so reporting it answers questions that logs answer only indirectly: whether a subsystem is running, whether it has been restarting in a loop, and which part of the tree is accumulating memory.</p><p>Each node reports:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>name</code></td><td>The process&#39;s name, as registered with its supervisor.</td></tr><tr><td><code>kind</code></td><td>Whether the node is a supervisor or a leaf worker.</td></tr><tr><td><code>state</code></td><td><code>running</code>, <code>exited</code> (ran and was not restarted), or <code>registered</code> (declared but not currently running).</td></tr><tr><td><code>process_id</code></td><td>The identifier of the node&#39;s most recent process. A restart produces a new one.</td></tr><tr><td><code>process_name</code></td><td>The fully qualified, dot-scoped process name.</td></tr><tr><td><code>restart</code></td><td>The node&#39;s restart policy: <code>permanent</code>, <code>transient</code>, or <code>temporary</code>.</td></tr><tr><td><code>created_at</code></td><td>When the node first became part of the tree. Constant across restarts.</td></tr><tr><td><code>started_at</code>, <code>uptime_ms</code></td><td>When the node&#39;s most recent process started, and how long it has been running.</td></tr><tr><td><code>restart_count</code></td><td>Restarts since the node was created, including those caused by its supervisor restarting.</td></tr><tr><td><code>resources</code></td><td>Allocation and CPU accounting, for supervisors.</td></tr><tr><td><code>supervision</code></td><td>Restart strategy, shutdown budget, and runtime placement, for supervisors.</td></tr></tbody></table><p>Two details are worth knowing before reading the numbers.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Resource figures are reported per supervisor, not per worker. A worker inherits its supervisor&#39;s resource group rather than owning one, so its allocations are already counted against the supervisor named in its <code>resource_group</code> field. Worker nodes therefore name a group but carry no figures of their own.</p></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Allocation figures require the tracking allocator, and CPU figures require per-thread CPU accounting. When either is unavailable, the counts read zero. Check the <code>resource_tracking_enabled</code> field, or the <code>resource tracking off</code> line in the tree output, to tell nothing allocated from nothing measuring.</p></div><p>The difference between <code>created_at</code> and <code>started_at</code> is the time a node has spent <em>not</em> running since it was created, which is the figure worth looking at when something is restarting repeatedly.</p><p>A statically declared process that exits without being restarted stays in the tree as <code>exited</code>, because it remains part of ADP&#39;s declared shape. Dynamically spawned processes, such as one per connection, are removed once they finish, so the tree does not grow without bound.</p><p>A node that has run keeps <code>process_id</code>, <code>process_name</code>, and <code>started_at</code> after it stops, so a stopped process still says what it ran as. Read <code>state</code> to tell whether that process is the current one, and <code>uptime_ms</code>, which is present only while a node is running. These three fields are absent only for a node that has never run.</p><h2 id="show-the-tree" tabindex="-1">Show the tree <a class="header-anchor" href="#show-the-tree" aria-label="Permalink to &quot;Show the tree&quot;">​</a></h2><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ agent-data-plane debug runtime show-processes</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Supervision tree for &#39;adp-root&#39;, captured 2026-09-03T12:00:00Z</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  54 processes (14 supervisors, 40 workers): 53 running, 1 exited, 0 registered</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  3 restarts across the tree, max depth 5</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  resource tracking on: 24.1 MiB live, 12.3s CPU</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">adp-root  [sup] running  pid=1  up=2h15m  one_for_one(0/5s)  live=1.2 MiB</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">|-- app-bootstrap  [sup] running  pid=3  up=2h15m  one_for_one(1/5s)  live=104.0 KiB</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">|   |-- logging  [sup] running  pid=4  up=2h15m  one_for_one(1/5s)  live=12.0 KiB</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">|   |   \`-- level-override-processor  [worker] running  pid=5  up=2h15m</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">|   \`-- metrics  [sup] running  pid=6  up=2h15m  one_for_one(1/5s)  live=92.0 KiB</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">|       |-- flusher  [worker] running  pid=7  up=2h15m</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">|       \`-- reflector  [worker] running  pid=8  up=2h15m</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">|-- internal-sup  [sup] running  pid=10  up=2h15m  one_for_one(1/5s)  live=890.0 KiB</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">|   \`-- ctrl-pln  [sup] running  pid=11  up=2h15m  restarts=1  one_for_one(1/5s)  rt=1thr  live=612.0 KiB</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`-- primary  [worker] running  pid=20  up=2h15m</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    \`-- topology.primary  [sup] running  pid=21  up=2h15m  one_for_one(0/5s)  live=18.4 MiB</span></span></code></pre></div><p>Indentation and branch glyphs show the nesting. A supervisor&#39;s line also carries its restart strategy as <code>mode(intensity/period)</code>, and <code>rt=Nthr</code> when it runs on its own runtime rather than its parent&#39;s.</p><p>Nodes that need attention stand out without needing color: <code>restarts=</code> appears only when a node has actually restarted, and a stopped process is marked <code>EXITED</code> in capitals.</p><h2 id="change-the-output-format" tabindex="-1">Change the output format <a class="header-anchor" href="#change-the-output-format" aria-label="Permalink to &quot;Change the output format&quot;">​</a></h2><p>Use <code>--format</code> (<code>-f</code>) to select the output format. The default is <code>tree</code>.</p><p>Pass <code>--json</code> (<code>-j</code>), or <code>--format json</code>, to get the endpoint&#39;s payload unchanged. The payload is passed through verbatim rather than re-serialized, so fields the CLI does not yet know about still reach whatever consumes it:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ agent-data-plane debug runtime show-processes --json </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.totals&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ agent-data-plane debug runtime show-processes --json </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.. | objects | select(.restart_count &gt; 0) | .process_name&#39;</span></span></code></pre></div><p>Pass <code>--format dot</code> to emit a <a href="https://graphviz.org" target="_blank" rel="noreferrer">Graphviz</a> graph. Supervisors are drawn with a bold border, stopped processes are filled, and processes that are declared but not running are dashed:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ agent-data-plane debug runtime show-processes --format dot </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> dot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Tsvg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tree.svg</span></span></code></pre></div><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>/runtime/processes</code></td><td><code>GET</code></td><td>A snapshot of the supervision tree, as JSON.</td></tr></tbody></table><p>The route is served on the privileged API endpoint (<code>data_plane.secure_api_listen_address</code>, <code>tcp://0.0.0.0:5101</code> by default), which requires the IPC client certificate. A snapshot names every process and reports its resource accounting, so it is authenticated the same way as the other state dumps such as <code>/config</code> and <code>/config/runtime</code>.</p><p>The same snapshot is collected into support flares as <code>supervision_tree.json</code>.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Process names are shared across ADP&#39;s registries, so a snapshot joins against <code>/memory/status</code>, <code>/ready</code>, and <code>resources.json</code> on the <code>process_name</code> field with no translation.</p></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>A supervisor running on its own runtime, such as <code>ctrl-pln</code>, reports an unscoped process name (<code>ctrl_pln</code> rather than <code>adp_root.internal_sup.ctrl_pln</code>), because it re-roots its name when it starts. <code>/memory/status</code> additionally lists a scoped entry for such a supervisor that always reads zero. Both are known defects; the tree reports the name that the supervisor&#39;s allocations are actually attributed to.</p></div>`,28)])])}const g=s(r,[["render",o]]);export{u as __pageData,g as default};
